package org.example.wastebag.model;

/** 垃圾袋生命周期状态 */
public enum BagStatus {
    /** 已发放给业主 */
    ISSUED,
    /** 未使用已退回物业 */
    RETURNED,
    /** 已被清运员扫码收走 */
    CLEARED,
    /** 业主报失（按约定赔付） */
    LOST
}

package org.example.wastebag.model;

/** 袋号事件类型（领用/退袋/清运/报失/破损） */
public enum EventType {
    ISSUE,
    RETURN,
    CLEAR,
    LOST,
    DAMAGE
}

package org.example.wastebag.model;

/** 账单状态：出账中 -> 已结算 -> 已支付 */
public enum BillStatus {
    OPEN,
    SETTLED,
    PAID
}

package org.example.wastebag.model;

/** 账单/补差单明细类型 */
public enum ItemType {
    /** 清运费（按实际清运袋数） */
    CLEARANCE_FEE,
    /** 遗失赔付（按约定） */
    LOST_FEE,
    /** 补差单手工补收 */
    ADJUST_DEBIT,
    /** 补差单手工退回（负数金额也可直接用 CREDIT 正数表示冲减） */
    ADJUST_CREDIT
}

package org.example.wastebag.model;

import io.quarkus.hibernate.orm.panache.PanacheEntity;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Table;

/** 业主 */
@Entity
@Table(name = "owner")
public class Owner extends PanacheEntity {

    @Column(nullable = false)
    public String name;

    /** 房号，如 3-2-501 */
    @Column(nullable = false, unique = true)
    public String unit;

    public String phone;
}

package org.example.wastebag.model;

import io.quarkus.hibernate.orm.panache.PanacheEntity;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;

import java.time.LocalDateTime;

/**
 * 垃圾袋。袋号全局唯一，全生命周期（含破损、跨月清运）只沿用这一个袋号，
 * 不另建袋记录，避免重复计费。
 */
@Entity
@Table(name = "bag")
public class Bag extends PanacheEntity {

    @Column(nullable = false, unique = true)
    public String bagNo;

    @ManyToOne(optional = false, fetch = FetchType.EAGER)
    @JoinColumn(name = "owner_id")
    public Owner owner;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    public BagStatus status;

    public LocalDateTime issuedAt;
    public LocalDateTime returnedAt;
    public LocalDateTime clearedAt;

    /** 破损标记：破损袋仍用原袋号清运，仅作标记 */
    public boolean damaged;

    public static Bag findByBagNo(String bagNo) {
        return find("bagNo", bagNo).firstResult();
    }
}

package org.example.wastebag.model;

import io.quarkus.hibernate.orm.panache.PanacheEntity;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 袋号事件流水：领用、退袋、清运、报失、破损。
 * 账单与补差单的费用都从这里派生；billed 标记保证同一事件只计费一次。
 */
@Entity
@Table(name = "bag_event")
public class BagEvent extends PanacheEntity {

    @Column(nullable = false)
    public String bagNo;

    @ManyToOne(optional = false, fetch = FetchType.EAGER)
    @JoinColumn(name = "owner_id")
    public Owner owner;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    public EventType type;

    @Column(nullable = false)
    public LocalDateTime occurredAt;

    /** 事件归属账期 yyyy-MM（按发生时间），跨月清运时费用落在清运当月 */
    @Column(nullable = false, length = 7)
    public String month;

    public String operator;

    public String note;

    /** 是否已计入账单或补差单（防重复计费的落库标记） */
    @Column(nullable = false)
    public boolean billed = false;

    public static BagEvent findClearEvent(String bagNo) {
        return find("bagNo = ?1 and type = ?2", bagNo, EventType.CLEAR).firstResult();
    }

    public static List<BagEvent> unbilledOfType(Long ownerId, String month, EventType type) {
        return list("owner.id = ?1 and month = ?2 and type = ?3 and billed = false",
                ownerId, month, type);
    }

    public static List<BagEvent> ofMonth(Long ownerId, String month) {
        return list("owner.id = ?1 and month = ?2 order by occurredAt, id", ownerId, month);
    }
}

