package org.example.wastebag.model;

import io.quarkus.hibernate.orm.panache.PanacheEntity;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import jakarta.persistence.UniqueConstraint;

import java.time.LocalDateTime;

/**
 * 月度账单。每个业主每个账期最多一张；结算后内容冻结，
 * 之后的差错一律通过补差单（Adjustment）修正，原账单不变。
 */
@Entity
@Table(name = "bill", uniqueConstraints = @UniqueConstraint(columnNames = {"owner_id", "month"}))
public class Bill extends PanacheEntity {

    @ManyToOne(optional = false, fetch = FetchType.EAGER)
    @JoinColumn(name = "owner_id")
    public Owner owner;

    /** 账期 yyyy-MM */
    @Column(nullable = false, length = 7)
    public String month;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    public BillStatus status = BillStatus.OPEN;

    @Column(nullable = false)
    public LocalDateTime createdAt;

    public LocalDateTime settledAt;

    public static Bill findByOwnerAndMonth(Long ownerId, String month) {
        return find("owner.id = ?1 and month = ?2", ownerId, month).firstResult();
    }
}

package org.example.wastebag.model;

import io.quarkus.hibernate.orm.panache.PanacheEntity;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;

import java.time.LocalDateTime;

/**
 * 补差单：已结算账单的差错更正载体。原账单保持不变，
 * 补收/退回金额都体现在补差单明细里，单独支付。
 */
@Entity
@Table(name = "adjustment")
public class Adjustment extends PanacheEntity {

    @ManyToOne(optional = false, fetch = FetchType.EAGER)
    @JoinColumn(name = "bill_id")
    public Bill bill;

    @Column(nullable = false)
    public String reason;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    public AdjustmentStatus status = AdjustmentStatus.OPEN;

    @Column(nullable = false)
    public LocalDateTime createdAt;

    public enum AdjustmentStatus {
        OPEN, PAID
    }
}

package org.example.wastebag.model;

import io.quarkus.hibernate.orm.panache.PanacheEntity;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;

import java.math.BigDecimal;
import java.util.List;

/**
 * 费用明细。挂在账单或补差单上（二选一）。
 * 由事件派生的明细带 event 引用；手工补差明细 event 为空。
 */
@Entity
@Table(name = "bill_item")
public class BillItem extends PanacheEntity {

    @ManyToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "bill_id")
    public Bill bill;

    @ManyToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "adjustment_id")
    public Adjustment adjustment;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    public ItemType type;

    /** 关联袋号（手工调整可为空） */
    public String bagNo;

    @ManyToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "event_id")
    public BagEvent event;

    @Column(nullable = false, precision = 10, scale = 2)
    public BigDecimal amount;

    public String description;

    public static List<BillItem> ofBill(Long billId) {
        return list("bill.id = ?1 order by id", billId);
    }

    public static List<BillItem> ofAdjustment(Long adjustmentId) {
        return list("adjustment.id = ?1 order by id", adjustmentId);
    }
}

